};

/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {void}
 * @hidden N
 */
scwin.setCode = function() {
    scwin.setCode1();
    scwin.setCode2();
};

/**
 * @method
 * @name setCode1
 * @description set Code1 처리
 * @returns {void}
 * @hidden N
 */
scwin.setCode1 = function() {
    txb_EMP_NO.setValue(scwin.gEmpNo);
    txb_dep_cd.setValue(scwin.gDepCd);
    txb_fromName.setValue(scwin.gEmpNm);
};

/**
 * @method
 * @name setCode2
 * @description set Code2 처리
 * @returns {void}
 * @hidden N
 */
scwin.setCode2 = function() {
    txb_fromCellNo.setValue("02-3774-9000");
};

/**
 * @method
 * @name getListSmsTp
 * @description get List Sms Tp 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getListSmsTp = async function() {
    const sbmOptions = {
        id : "sbm_dts_Msg",
        action : "/NoteMgt.do",
        ref : "",
        target : "dts_Msg=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name setHeader
 * @description set Header 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setHeader = async function() {
    const sbmOptions = {
        id : "sbm_dts_Master",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_Master=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_Master.AddRow();
