/**
 * @method
 * @name initPage
 * @description init Page 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.initPage = async function() {
    const ToDay = $c.ut.cGetToday2();
    edt_EDATE.setValue(ToDay);
    const vSDATE = $c.ut.calcMonth(ToDay, -6);
    edt_SDATE.setValue(vSDATE);
    await scwin.getListSmsTp();
};

/**
 * @method
 * @name readSendSMS
 * @description read Send SMS 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readSendSMS = async function(row, colid) {
    if (colid === "CONTN") {

        scwin.gNOTI_SVC_ID = dts_Grid.NameString(row, "NOTI_SVC_ID");
        const sbmOptions = {
            id : "sbm_dts_Master",
            action : "/NoteMgt.do",
            ref : "",
            target : "dts_Master=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        // alert(dts_Master.NameString(row, "SND_CHRG_EMP_NM") + "\n" + dts_Master.NameString(row, "SND_NO"));

        const sbmOptions2 = {
            id : "sbm_dts_Receiver",
            action : "/NoteMgt.do",
            ref : "",
            target : "dts_Receiver=body.content",
            isProcessMsg : false
        };

        const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
        // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    }
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    if ($c.stf.compareFromToDate2(edt_SDATE, edt_EDATE) === false) {
        return;
    }
    url += "&MDTYPE=E"; // EXTURE 회원사 SMS알림:E
    url += "&SDATE=" + edt_SDATE.getValue();
    url += "&EDATE=" + edt_EDATE.getValue();
    url += "&DEP_CD=" + scwin.gDepCd;
    url += "&NOTI_SVC_ID=";
    url += "&SCREN_ID=" + "ULDSTF30375.gfm";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_Grid",
        action : "/NoteMgt.do",
        ref : "",
        target : "dts_Grid=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name rowCount
 * @description row Count 처리
 * @returns {void}
 * @hidden N
 */
scwin.rowCount = function() {
    txb_receiver_cnt.setValue("총 : " + dts_Receiver.CountRow + " 건");
};

/**
 * @method
 * @name smsTpSelect
 * @description sms Tp Select 처리
 * @returns {void}
 * @hidden N
 */
scwin.smsTpSelect = function() {

    const vSelectedVal = cmb_SmsTp.ValueOfIndex("VALUE", cmb_SmsTp.Index);
    txa_CONTN.setValue(vSelectedVal);
};

/**
 * @method
 * @name registerSMS
 * @description register SMS 처리
 * @returns {void}
 * @hidden N
 */
scwin.registerSMS = function() {
    if (scwin.fn_CheckForm()) {
        let msg = $c.stf.getMessageParam("MSG-A006", "전송");
        scwin.setCode1(); // 보내는 사람,이름,부서 고정

        if (window.confirm(msg)) {

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            //
            // ********************************************************************

            let url = "/SmsMgt.do?method=registerSmsSendToExturePlusMbr" + "&SCREN_ID=" + "ULDSTF30375.gfm" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02; /*ORG SRC: dts_Master.NameString(1, "TITLE") = getObjectText(cmb_SmsTp);*/ X = $c.stf.getObjectText(cmb_SmsTp);
            /*

            alert(dts_Master.NameString(1, "SND_CHRG_EMP_NO")

              + "\n" + dts_Master.NameString(1, "SND_NO")

              + "\n" + dts_Master.NameString(1, "DEP_CD")

              + "\n" + dts_Master.NameString(1, "TITLE"));
             */
            for (let i = 1; i <= dts_Receiver.CountRow; i++) {

                // ********************************************************************
                // [WebSquare 전환 추가] 원본 소스와 비교 필요
                //
                // ********************************************************************

                /*ORG SRC: dts_Receiver.NameString(i, "EMP_NO") = gEmpNo; //수정상태로 변경*/
                X = scwin.gEmpNo; // 수정상태로 변경

            }
            trs_Save.Action = url;
            trs_Save.KeyName = "toinb_dataid4";
            trs_Save.KeyValue = "JSP(I:pInputMaster=dts_Master, I:pInputDetail=dts_Receiver)";

            trs_Save.post();
        }
    }
};
$c.en.fn_CheckForm = function() {
    let msg = "";
    if (txa_CONTN.getValue() === "") {
        msg = $c.stf.getMessageParam("MSG-A005", "보내는 내용");
        alert(msg);

        txa_CONTN.Focus();
        return false;
    }
    // setObjectValue(txb_title_size, getStringSize(getObjectValue(txa_CONTN)));

    if ($c.stf.getStringSize(txa_CONTN.getValue()) > 2000) {
        alert('보내는내용이 2000Byte가 초과되었습니다.');

        txa_CONTN.Focus();
        return false;
    }
    if (txb_fromCellNo.getValue() === "" || txb_fromCellNo.getValue() === "-") {
        msg = $c.stf.getMessageParam("MSG-A005", "보내는 번호");
        alert(msg);

        txb_fromCellNo.focus();
        return false;
    }
    if (!$c.stockSearch.isNumber(txb_fromCellNo.getValue())) {
        alert("[보내는 번호]를 숫자로 입력해주세요.");

        txb_fromCellNo.focus();
        return;
    }
    if (dts_Receiver.CountRow === 0) {
        alert("선택된 수신자가 없습니다.");
        return false;
    }

    // 휴대폰번호 확인
    const regExpCell = /^01(?:0|1|[6-9])(?:\d{4})\d{4}$/; // 정규식 체크 - 휴대폰번호
    let cellphoneNo = "";
    for (let i = 1; i <= dts_Receiver.CountRow; i++) {

        cellphoneNo = (dts_Receiver.NameString(i, "CELLPHONE_NO")).replace(/-/g, "");
        if (!regExpCell.test(cellphoneNo)) {
            alert("[휴대전화번호]를 확인해 주세요.");
            dts_Receiver.RowPosition = i;

            grd_Receiver.SetColumn("CELLPHONE_NO");

            grd_Receiver.focus();
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name new
 * @description new 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.new = async function() {
    scwin.setCode();
    await scwin.setHeaderRcvr();
};

/**
 * @method
 * @name addRow
 * @description add Row 처리
 * @param {*} bnd bnd
 * @param {*} grid grid
 * @param {*} column_nm column_nm
 * @param {*} focus_yn focus_yn
 * @returns {void}
 * @hidden N
 */
scwin.addRow = function(bnd, grid, column_nm, focus_yn) {

    bnd.addRow();

    if (focus_yn !== "N") {

        grid.SetColumn(column_nm);

        grid.Focus();
    }
};

/**
 * @method
 * @name deleteRow
 * @description delete Row 처리
 * @param {*} bnd bnd
 * @param {*} grid grid
 * @returns {void}
 * @hidden N
 */
scwin.deleteRow = function(bnd, grid) {

    bnd.deleterow(bnd.rowposition);

    grid.Focus();
};

/**
 * @method
 * @name addRcvOper
 * @description add Rcv Oper 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.addRcvOper = async function() {
    await scwin.searchRcvOper();
};

/**
 * @method
 * @name searchRcvOper
 * @description search Rcv Oper 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchRcvOper = async function() {
    url += "&DEP_CD=" + scwin.gDepCd;
    url += "&SCREN_ID=" + "ULDSTF30375.gfm";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_Oper",
        action : "/NoteMgt.do",
        ref : "",
        target : "dts_Oper=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name addRowFromRcvOper
 * @description add Row From Rcv Oper 처리
 * @returns {void}
 * @hidden N
 */
scwin.addRowFromRcvOper = function() {
    grd_Receiver.Redraw = false;
    let j = 1 + dts_Receiver.CountRow;
    for (let i = 1; i <= dts_Oper.CountRow; i++) {

        const vLength = dts_Oper.NameString(i, "CELLPHONE_NO").length;
        if (vLength > 0) {

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            //
            // ********************************************************************

            dts_Receiver.AddRow(); /*ORG SRC: dts_Receiver.NameString(j, "EXTUREPLUS_MBR_ID") = dts_Oper.NameString(i, "EXTUREPLUS_MBR_ID");*/ X = dts_Oper.NameString(i, "EXTUREPLUS_MBR_ID"); /*ORG SRC: dts_Receiver.NameString(j, "EXTUREPLUS_MBR_NM") = dts_Oper.NameString(i, "EXTUREPLUS_MBR_NM");*/ X = dts_Oper.NameString(i, "EXTUREPLUS_MBR_NM"); /*ORG SRC: dts_Receiver.NameString(j, "DEP_NM") = dts_Oper.NameString(i, "DEP_NM");*/ X = dts_Oper.NameString(i, "DEP_NM"); /*ORG SRC: dts_Receiver.NameString(j, "CHRG_NM") = dts_Oper.NameString(i, "CHRG_NM");*/ X = dts_Oper.NameString(i, "CHRG_NM"); /*ORG SRC: dts_Receiver.NameString(j, "JOBTITL_NM") = dts_Oper.NameString(i, "JOBTITL_NM");*/ X = dts_Oper.NameString(i, "JOBTITL_NM"); /*ORG SRC: dts_Receiver.NameString(j, "TEL_NO") = dts_Oper.NameString(i, "TEL_NO");*/ X = dts_Oper.NameString(i, "TEL_NO"); /*ORG SRC: dts_Receiver.NameString(j, "CELLPHONE_NO") = dts_Oper.NameString(i, "CELLPHONE_NO");*/ X = dts_Oper.NameString(i, "CELLPHONE_NO");
            j++;
        }
    }
    grd_Receiver.Redraw = true;
    scwin.rowCount();
};

/**
 * @method
 * @name grd_Grid_CanColumnPosChange
 * @description grd Grid Can Column Pos Change 처리
